def par_ou_impar(numero):
    if numero % 2 == 0:
        return "par"
    return "ímpar"

print(par_ou_impar(4))  # par
print(par_ou_impar(7))  # ímpar

def converter_temperatura(celsius, para="F"):
    if para == "F":
        return celsius * 9 / 5 + 32
    if para == "K":
        return celsius + 273.15
    return None

print(converter_temperatura(25))           # 77.0
print(converter_temperatura(25, para="K")) # 298.15
print(converter_temperatura(25, "X"))      # None

def media(*notas):
    if len(notas) == 0:
        return 0
    return sum(notas) / len(notas)

print(media(8, 7, 9))  # 8.0
print(media())         # 0

def resumo_notas(notas):
    return min(notas), max(notas), sum(notas) / len(notas)

menor, maior, media_turma = resumo_notas([6.5, 9, 7.5, 8])
print(menor, maior, media_turma)  # 6.5 9 7.75

def cadastrar(nome, **extras):
    ficha = {"nome": nome}
    ficha.update(extras)
    return ficha

print(cadastrar("Ana", idade=20, cidade="Salvador"))
# {'nome': 'Ana', 'idade': 20, 'cidade': 'Salvador'}

